4377	// ---------------------------------------------------------------------------
4378	// 资源临时停用：场地维护、设备检修、人员休息
4379	// 实际可用时间 = 原开放区间合并后扣除全部有效停用区间的并集（原开放记录保留）
4380	// ---------------------------------------------------------------------------
4381	
4382	const CLOSURE_STATUS_LABEL: Record<ClosureStatus, string> = {
4383	  active: '有效',
4384	  cancelled: '已取消',
4385	};
