4387	async function cmdAddClosure(args: string[]): Promise<void> {
4388	  const {values, positionals} = parseFlags(args, ['resource', 'start', 'end']);
4389	  if (positionals.length > 0) throw new UsageError(`add-closure 不接受位置参数: ${positionals.join(' ')}`);
4390	
4391	  const resourceId = requireFlag(values, 'resource');
4392	  const startRaw = requireFlag(values, 'start');
4393	  const endRaw = requireFlag(values, 'end');
4394	
4395	  const file = activeDataFile;
4396	  const store = await loadStoreForWrite(file);
4397	
4398	  const resource = store.resources.find((r) => r.id === resourceId);
4399	  if (!resource) throw new BizError(`未知资源标识: ${resourceId}`);
4400	
4401	  const startMin = parseDateTime(startRaw, '停用开始时间');
4402	  const endMin = parseDateTime(endRaw, '停用结束时间');
4403	  if (endMin <= startMin) {
4404	    throw new BizError(`停用结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
4405	  }
4406	
4407	  // 登记前检查该资源的全部有效预约（含系列成员与候补兑现预约；已取消不阻挡）。
4408	  // 区间左闭右开，端点相接不算重叠；有重叠即拒绝，不改期或取消任何预约。
4409	  const affected = store.bookings
4410	    .filter((b) => {
4411	      if (b.status !== 'active' || !b.resourceIds.includes(resourceId)) return false;
4412	      const bs = parseDateTime(b.start, '预约开始时间');
4413	      const be = parseDateTime(b.end, '预约结束时间');
4414	      return bs < endMin && startMin < be;
4415	    })
4416	    .sort((a, b) => a.id.localeCompare(b.id));
4417	  if (affected.length > 0) {
4418	    const lines = affected.map((b) => `- ${b.id}（${b.start} → ${b.end}）`);
4419	    throw new BizError(
4420	      `无法登记停用：资源 ${resourceId}（${resource.name}）在该区间存在有效预约` +
4421	        `（不自动改期或取消，请先处理）：\n${lines.join('\n')}`,
4422	    );
4423	  }
4424	
4425	  // 全部校验通过后才生成标识、改内存、落盘；相同内容再次登记也是另一记录
4426	  store.closureSeq += 1;
4427	  const id = `C${String(store.closureSeq).padStart(4, '0')}`;
4428	  store.closures.push({id, resourceId, start: startRaw, end: endRaw, status: 'active'});
4429	  store.closures.sort((a, b) => a.id.localeCompare(b.id));
4430	  await saveStore(file, store);
4431	  console.log(`已登记停用 ${id}`);
4432	  console.log(`  资源: ${resourceId}（${resource.name}）`);
4433	  console.log(`  时间: ${startRaw} → ${endRaw}`);
4434	  console.log('  该区间不再计入实际可用时间；取消停用请使用 cancel-closure。');
4435	}
