4437	async function cmdListClosures(args: string[]): Promise<void> {
4438	  const {values, positionals} = parseFlags(args, []);
4439	  if (values.size > 0) {
4440	    throw new UsageError(`list-closures 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`);
4441	  }
4442	  if (positionals.length > 0) {
4443	    throw new UsageError(`list-closures 不接受位置参数: ${positionals.join(' ')}`);
4444	  }
4445	
4446	  const store = await loadStore(activeDataFile);
4447	  if (store.closures.length === 0) {
4448	    console.log('暂无停用记录。可使用 add-closure 登记场地维护、设备检修或人员休息。');
4449	    return;
4450	  }
4451	  const sorted = [...store.closures].sort(
4452	    (a, b) =>
4453	      parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
4454	      a.id.localeCompare(b.id),
4455	  );
4456	  console.log(`停用记录（共 ${sorted.length} 条，按开始时间、标识排序）：`);
4457	  for (const c of sorted) {
4458	    console.log(`- ${c.id} [${CLOSURE_STATUS_LABEL[c.status]}] ${c.start} → ${c.end}`);
4459	    console.log(`    资源: ${formatResourceIds(store, [c.resourceId])}`);
4460	  }
4461	}
