4463	async function cmdCancelClosure(args: string[]): Promise<void> {
4464	  const {values, positionals} = parseFlags(args, []);
4465	  if (values.size > 0) {
4466	    throw new UsageError(`cancel-closure 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`);
4467	  }
4468	  if (positionals.length !== 1) throw new UsageError('用法: cancel-closure <停用标识>');
4469	  const id = positionals[0];
4470	  if (!/^C\d{4,}$/.test(id)) throw new BizError(`停用标识非法: ${id}`);
4471	
4472	  const file = activeDataFile;
4473	  const store = await loadStoreForWrite(file);
4474	  const closure = store.closures.find((c) => c.id === id);
4475	  if (!closure) throw new BizError(`未知停用标识: ${id}`);
4476	  if (closure.status === 'cancelled') {
4477	    // 幂等：重复取消成功且不做任何改动
4478	    console.log(`停用 ${id} 已是取消状态，未做改动。`);
4479	    return;
4480	  }
4481	  // 仅使该记录失效并保留历史；其他重叠停用仍有效，不自动创建预约或处理候补
4482	  closure.status = 'cancelled';
4483	  await saveStore(file, store);
4484	  console.log(`已取消停用 ${id}（记录保留），该区间恢复可用（不超出原开放时间）。`);
4485	}
