4112	async function cmdRescheduleFlex(args: string[]): Promise<void> {
4113	  const {values, positionals} = parseFlags(args, []);
4114	  if (values.size > 0) {
4115	    throw new UsageError(
4116	      `reschedule-flex 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
4117	    );
4118	  }
4119	  if (positionals.length !== 1) {
4120	    throw new UsageError('用法: reschedule-flex <改期清单文件>');
4121	  }
4122	  const manifestFile = positionals[0];
4123	
4124	  // 修改入口：先取得写入保护再读最新数据，求解至保存全程受保护
4125	  const file = activeDataFile;
4126	  const store = await loadStoreForWrite(file);
4127	  const records = parseFlexRescheduleShape(await loadManifest(manifestFile), manifestFile);
4128	  const items = parseFlexRescheduleItems(store, records, manifestFile);
4129	
4130	  const plan = solveFlexReschedule(store, items);
4131	  if (plan === null) {
4132	    throw new BizError(
4133	      `无整体解：清单 ${manifestFile} 的 ${items.length} 项改期不存在同时可行的安排` +
4134	        '（每项须完整落在自身窗口内，各组所选资源互不相同并全程固定，' +
4135	        '本批之间共同资源时间不得重叠）。未改动任何预约，数据文件与标识计数未改动。',
4136	    );
4137	  }
4138	
4139	  // 展开各项最终安排（开始分钟 -> 文本；窗口已校验在 0001-9999 内，时段不超出窗口）
4140	  const resolved = items.map((it, i) => {
4141	    const p = plan[i];
4142	    const start = formatDateTime(p.startMin);
4143	    const end = formatDateTime(p.endMin);
4144	    if (start === null || end === null) {
4145	      // 理论不可达：窗口已校验在四位年份内，时段不超出窗口
4146	      throw new BizError('可行时段超出四位年份范围');
4147	    }
4148	    const isChanged = !(p.startMin === it.curStartMin && sameResourceSet(p.picks, it.curResourceIds));
4149	    return {item: it, start, end, picks: p.picks, changed: isChanged};
4150	  });
4151	
4152	  const printPlan = (): void => {
4153	    for (const r of resolved) {
4154	      const b = r.item.booking;
4155	      console.log(
4156	        `- 第 ${r.item.index} 项 ${b.id}` +
4157	          (b.seriesId !== undefined ? `（系列 ${b.seriesId}，归属不变）` : '') +
4158	          `: ${r.start} → ${r.end}（${r.item.duration} 分钟）`,
4159	      );
4160	      r.picks.forEach((id, g) => {
4161	        const res = store.resources.find((x) => x.id === id)!;
4162	        console.log(`    第 ${g + 1} 组: ${id}（${res.name}，${RESOURCE_TYPE_LABEL[res.type]}）`);
4163	      });
4164	    }
4165	  };
4166	
4167	  // 无变化：成功但不写文件、不建记录、不推进计数
4168	  if (resolved.every((r) => !r.changed)) {
4169	    console.log(
4170	      `弹性批量改期成功：共 ${resolved.length} 项，安排均与现状一致，无业务变化` +
4171	        '（标识与系列归属不变，未生成改期操作记录，数据文件与标识计数未改动）',
4172	    );
4173	    printPlan();
4174	    return;
4175	  }
4176	
4177	  // 至少一项有变化：将全部提交项的前后完整安排、系列归属及清单顺序记为一条
4178	  // “未撤销”批量改期操作记录，与新安排在同一次原子保存中落盘后才报告成功；
4179	  // 保存失败则不留记录、不推进计数。仅改时间与资源；标识、status、seriesId、
4180	  // 导入身份与候补关联、其余标识计数全部不变，不创建任何预约或系列。
4181	  const opItems: BatchOpItem[] = resolved.map((r) => {
4182	    const b = r.item.booking;
4183	    const item: BatchOpItem = {
4184	      bookingId: b.id,
4185	      before: {start: b.start, end: b.end, resourceIds: [...b.resourceIds]},
4186	      after: {start: r.start, end: r.end, resourceIds: [...r.picks].sort()},
4187	    };
4188	    if (b.seriesId !== undefined) item.seriesId = b.seriesId;
4189	    return item;
4190	  });
4191	  store.batchSeq += 1;
4192	  const opId = `O${String(store.batchSeq).padStart(4, '0')}`;
4193	  for (const r of resolved) {
4194	    r.item.booking.start = r.start;
4195	    r.item.booking.end = r.end;
4196	    r.item.booking.resourceIds = [...r.picks].sort();
4197	  }
4198	  store.batchOps.push({id: opId, status: 'active', items: opItems});
4199	  await saveStore(file, store);
4200	
4201	  console.log(
4202	    `弹性批量改期成功：操作标识 ${opId}，共 ${resolved.length} 项` +
4203	      `（变化 ${resolved.filter((r) => r.changed).length} 项；仅改时间与资源，标识、状态与系列归属不变，未创建预约或系列）`,
4204	  );
4205	  printPlan();
4206	  console.log(`本次改期已记录为 ${opId}：可用 list-batch-ops 查询，undo-batch-op ${opId} 整笔安全撤销。`);
4207	}
