    try {
      await readFile(go, 'utf8');
      return;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== 'ENOENT') {
        throw new BizError(`测试同步点 ${name} 无法读取: ${(err as Error).message}`);
      }
      if (Date.now() >= deadline) throw new BizError(`测试同步点 ${name} 等待超时`);
