// 7. 混合身份：系列成员/导入预约/候补兑现预约同批腾挪，归属与关联全部保留
// ---------------------------------------------------------------------------

test('混合身份：系列/导入/候补兑现预约同批改期，归属、导入身份与候补关联保留', (t) => {
  const dir = tempDir(t);
